static int countRecords(List<String> lines) {
    int i = 0;
    int records = 0;
    while (i < lines.size()) {
        String line = lines.get(i);
        if (line.startsWith("#")) continue;    // skip comments
        records++;
        i++;
    }
    return records;
}

